<?php require __DIR__ . '/includes/config.php'; if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);redirect('cart.php');}if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['quantity']??[] as $id=>$quantity){if((int)$quantity>0)$_SESSION['cart'][(int)$id]=(int)$quantity;else unset($_SESSION['cart'][(int)$id]);}flash('success','Cart updated.');redirect('cart.php');}$items=cart_items($pdo);$total=cart_total($items);$pageTitle='Your cart';require __DIR__ . '/includes/header.php'; ?>
<section class="container py-5"><div class="eyebrow">Your edit</div><h1 class="display-5 mb-4">Shopping cart</h1><?php if(!$items): ?><div class="panel text-center py-5"><h2 class="h4">Your cart is waiting.</h2><a href="index.php" class="btn btn-dark mt-3">Continue shopping</a></div><?php else: ?><form method="post"><div class="row g-4"><div class="col-lg-8"><?php foreach($items as $item): ?><div class="panel d-flex align-items-center gap-3 mb-3"><img src="<?= e($item['image']) ?>" width="96" height="96" style="object-fit:cover" alt=""><div class="flex-grow-1"><h2 class="h5 mb-1"><?= e($item['name']) ?></h2><div class="text-secondary">$<?= number_format((float)$item['price'],2) ?></div></div><input class="form-control" style="width:80px" type="number" min="0" name="quantity[<?= $item['id'] ?>]" value="<?= $item['quantity'] ?>"><a class="text-danger" href="?remove=<?= $item['id'] ?>">Remove</a></div><?php endforeach; ?><button class="btn btn-outline-dark">Update cart</button></div><div class="col-lg-4"><div class="panel"><div class="d-flex justify-content-between"><span>Subtotal</span><strong>$<?= number_format($total,2) ?></strong></div><a class="btn btn-accent w-100 mt-4 py-2" href="checkout.php">Checkout</a></div></div></div></form><?php endif; ?></section><?php require __DIR__ . '/includes/footer.php'; ?>